import json,tomllib
from pathlib import Path
from scripts import check_sources,check_architecture
paths=[Path(p) for p in json.loads(Path(".workflow/manifest.json").read_text())["target_files"]]
policy=tomllib.loads(Path("pyproject.toml").read_text())["tool"]["gew"]["architecture"]
findings={"lint":[],"type":[],"architecture":check_architecture.validate_policy(policy)}
for p in paths:
 if p.suffix==".py":
  findings["lint"]+=check_sources.inspect_path(p,"lint",display_path=str(p))
  if p.parts[0]!="tests":findings["type"]+=check_sources.inspect_path(p,"type",display_path=str(p))
  if p.parts[0] in ("core","application","storage","adapters"):findings["architecture"]+=check_architecture.inspect_python(p,p.parts[0],policy)
print(json.dumps({"files":len(paths),"findings":findings},sort_keys=True))
raise SystemExit(int(any(findings.values())))
